import numpy as np
import time


def _score(h):
    """Exact R for step heights h, using FFT convolution for speed."""
    h = np.asarray(h, dtype=float)
    n = h.size
    m = 1
    while m < 2 * n:
        m <<= 1
    H = np.fft.rfft(h, m)
    conv = np.fft.irfft(H * H, m)[:2 * n - 1]
    L = np.empty(2 * n + 1)
    L[0] = 0.0
    L[1:2 * n] = conv
    L[2 * n] = 0.0
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if linf <= 0 or l1 <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _make(p, N, c=0.0, q=0.0):
    i = np.arange(N, dtype=float)
    x = (i + 0.5) / N
    h = x ** (-p)
    if c > 0.0 and q > 0.0:
        taper = 1.0 - c * x
        # guard against non-positive values (c<1 means taper>0 on (0,1))
        if np.any(taper <= 0.0):
            taper = np.maximum(taper, 1e-12)
        h = h * taper ** q
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    N = 200000
    best_h = None
    best_score = -1.0
    best_params = (0.5, 0.0, 0.0)

    def consider(p, c, q, n=N):
        nonlocal best_h, best_score, best_params
        if c >= 1.0 or c < 0.0 or q < 0.0:
            return -1.0
        h = _make(p, n, c, q)
        s = _score(h)
        if s > best_score:
            best_score = s
            best_h = h
            best_params = (p, c, q)
        return s

    # Coarse grid: p 7 values in [0.49,0.52], c 7 in [0,0.9], q 6 in [0,10]
    ps = np.linspace(0.49, 0.52, 7)
    cs = np.linspace(0.0, 0.9, 7)
    qs = np.linspace(0.0, 10.0, 6)

    for p in ps:
        for c in cs:
            for q in qs:
                if time.process_time() > deadline:
                    break
                consider(p, c, q)
            if time.process_time() > deadline:
                break
        if time.process_time() > deadline:
            break

    # Coordinate descent / Nelder-Mead style refinement on (p,c,q)
    # Use a simple adaptive coordinate descent with shrinking steps.
    if best_h is not None:
        p, c, q = best_params
        step = np.array([0.005, 0.1, 1.0])
        cur = np.array([p, c, q])
        cur_score = best_score
        while time.process_time() < deadline:
            improved = False
            for k in range(3):
                for sign in (1.0, -1.0):
                    if time.process_time() > deadline:
                        break
                    trial = cur.copy()
                    trial[k] += sign * step[k]
                    # bounds
                    trial[0] = min(max(trial[0], 0.45), 0.56)
                    trial[1] = min(max(trial[1], 0.0), 0.95)
                    trial[2] = min(max(trial[2], 0.0), 20.0)
                    if trial[1] >= 1.0:
                        continue
                    s = consider(trial[0], trial[1], trial[2])
                    if s > cur_score:
                        cur = trial
                        cur_score = s
                        improved = True
                        break
                if improved:
                    break
            if not improved:
                step *= 0.5
                if step[0] < 1e-5 and step[1] < 1e-4 and step[2] < 1e-3:
                    break

    # Keep start if better
    if start is not None:
        try:
            s_start = _score(np.asarray(start, dtype=float))
            if s_start > best_score:
                return np.asarray(start, dtype=float)
        except Exception:
            pass

    if best_h is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    print("best p=%.6f c=%.6f q=%.6f N=%d score=%.6f"
          % (best_params[0], best_params[1], best_params[2], N, best_score))
    return best_h
